const API = '/api';
let csrf = '';
async function api(path: string, method = 'GET', body?: unknown) {
  const multipart = body instanceof FormData;
  const response = await fetch(API + path, { method, credentials: 'include', headers: { ...(multipart ? {} : { 'Content-Type': 'application/json' }), 'X-CSRF-Token': csrf }, body: body === undefined ? undefined : multipart ? body : JSON.stringify(body) });
  const raw = await response.text();
  let result: any = {};
  try { result = raw ? JSON.parse(raw) : {}; }
  catch { result = { detail: response.ok ? 'Сервер вернул некорректный ответ' : 'Сервер временно не ответил. Повторите попытку.' }; }
  if (!response.ok) throw new Error(result.detail || 'Не удалось выполнить запрос');
  return result;
}
async function syncJob(kind:string) {
  let job = await api('/jobs/sync/'+kind,'POST');
  for(let attempt=0;attempt<1800;attempt++) {
    if(job.status==='completed') return job.result;
    if(['failed','interrupted'].includes(job.status)) throw new Error(job.result.message);
    await new Promise(resolve=>setTimeout(resolve,2000));
    job=await api('/jobs/'+job.id);
  }
  throw new Error('Синхронизация ещё выполняется. Проверьте состояние позже.');
}
